# This code has been fully generated by an AI.
"""Ablaufsteuerung: Arena-Ecken, Roboter-Vorschlag, Kampf. Verbindet Kamera, Modell, Tracking und Spiel.

Nach dem Setzen der Ecken gibt es nur noch die entzerrte Arena; alle Koordinaten im Zustand sind
Arena-Einheiten.
"""

import json
import logging
import math
import random
import threading
import time
from pathlib import Path

import cv2
import numpy as np

from .arena import UNITS, Arena, foreground, whiten
from .camera import Camera
from .config import BALANCING, Settings
from .game import Game, RobotInput
from .lobby import Lobby
from .tracking import Arbiter, Tracker

log = logging.getLogger(__name__)

CIRCLE_POINTS = 20
COUNTDOWN_S = 3.0
# In diesen Phasen stehen die Roboter schon fest und werden verfolgt.
LIVE_PHASES = ("intro", "ready", "countdown", "fight", "finished")
PROFILE_EMPTY = {"image": "", "team": "", "weight": "", "height": "", "slogan": ""}
# Rand ums Spielfeld im Bühnenbild (Arena-Einheiten); nur Optik, Erkennung und Ringout bleiben beim Feld.
VIEW_PAD = 80.0
# Spielzeit, nach der ein Medium spätestens endet, falls keine Bühne „ended“ meldet.
MEME_LIMIT_S = {"image": 6.5, "video": 30.0, "audio": 90.0}
CUTOUT_LIMIT_S = 120.0


class UserError(Exception):
    """Klartext-Meldung an die Bedienung."""


def _points(pts: np.ndarray | None) -> list[list[float]]:
    return [] if pts is None else np.asarray(pts, np.float32).round(1).tolist()


class App:
    def __init__(self, cfg: Settings, balancing_file: Path | None = None, lobby: Lobby | None = None):
        self.cfg = cfg
        self.lobby = lobby
        self._message = ""
        self.board_rev = 0
        self.keying: dict[str, float] = {}
        # Werte aus .env/Code merken, damit „Standardwerte“ dorthin zurückführt.
        self.balancing_defaults = {k: getattr(cfg, k) for k in BALANCING}
        self.balancing_file = balancing_file
        self._load_balancing()
        self.camera = Camera(cfg.camera, cfg.camera_width, cfg.camera_height)
        self.segmenter = None
        if cfg.segment_enabled:
            # Erst hier importiert: torch zu laden kostet Sekunden, auch wenn EdgeTAM aus ist.
            from .segmenter import Segmenter

            self.segmenter = Segmenter(cfg.model_id, cfg.torch_threads)
        self.arena: Arena | None = None
        self.tracker: Tracker | None = None
        self.phase = "arena"
        self.message = "Die vier Ecken der Arena anklicken."
        self.busy: str | None = None
        # Klicks der Bedienung je Roboter in Arena-Einheiten; legen fest, wer welcher ist.
        self.seeds: dict[int, tuple[float, float]] = {}
        self.proposal: list[np.ndarray | None] = [None, None]
        self.names = ["", ""]
        # Spieler, die sich mitten im Kampf anmelden, bekommen ihren Namen erst beim nächsten Kampf.
        self._pending_names: dict[int, str] = {}
        if lobby is not None:
            for p in lobby.public()["players"]:
                self.names[p["slot"] - 1] = p["name"]
        self.game: Game | None = None
        self.robots: list = []
        self.contact = False
        self.battle = 0
        self.hud = True
        # Steckbriefe für den VS-Bildschirm; überdauern Kämpfe, bis die Moderation sie ändert.
        self.profiles = [dict(PROFILE_EMPTY), dict(PROFILE_EMPTY)]
        # Laufende und pausierte Medien; der Server führt sie, damit alle Bühnen dasselbe zeigen.
        self.memes: list[dict] = []
        self._meme_ids = 0
        self._meme_rng = random.Random()
        # Kampfzeit in Kamerazeit: Beginn nach dem Intro, Ende beim K.o.
        self.phase_until = 0.0
        self.fight_start: float | None = None
        self.fight_end: float | None = None
        self.track_fps = 0.0
        self.latency_ms = 0.0
        self.track_error: str | None = None
        self.packet: tuple[int, bytes] = (0, b"")
        self._lock = threading.RLock()
        self._stop = threading.Event()

    @property
    def message(self) -> str:
        return self._message

    @message.setter
    def message(self, text: str) -> None:
        # Die Serverkonsole ist das Protokoll des Abends; jede neue Meldung gehört hinein.
        if text != self._message:
            log.info("%s", text)
        self._message = text

    # ---------- Lebenszyklus ----------

    def start(self) -> None:
        self.camera.start()
        if self.segmenter is not None:
            threading.Thread(target=self.segmenter.load, name="model-load", daemon=True).start()
        threading.Thread(target=self._loop, name="publish", daemon=True).start()
        # Eigener Thread, damit das Tracking die Anzeige nicht ausbremst.
        threading.Thread(target=self._track_loop, name="track", daemon=True).start()

    def stop(self) -> None:
        self._stop.set()
        self.camera.stop()

    def _background(self, label: str, fn) -> None:
        if self.busy:
            raise UserError(f"Bitte warten: {self.busy}")
        self.busy = label

        def run():
            try:
                fn()
            except UserError as exc:
                self.message = str(exc)
            except Exception as exc:  # noqa: BLE001 – sonst bliebe die Bedienung ohne Rückmeldung hängen.
                log.exception("%s fehlgeschlagen", label)
                self.message = f"{label} fehlgeschlagen: {exc}"
            finally:
                self.busy = None

        threading.Thread(target=run, name=label, daemon=True).start()

    # ---------- Aktionen der Bedienung ----------

    def act(self, action: str, data: dict) -> None:
        handler = getattr(self, f"do_{action}", None)
        if handler is None:
            raise UserError(f"Unbekannte Aktion '{action}'.")
        if self.busy and action not in ("camera", "abort", "spawn", "shrink", "hud", "profile", "cue", "ko",
                                        "ulti", "balancing", "balancing_reset", "name", "kick"):
            raise UserError(f"Bitte warten: {self.busy}")
        with self._lock:
            handler(**data)

    def do_camera(self, source: str) -> None:
        self.camera.start(str(source))
        self.message = f"Kamera '{source}' gestartet."

    def do_corners(self, points: list[list[float]]) -> None:
        if len(points) != 4:
            raise UserError("Genau vier Ecken anklicken.")
        try:
            arena = Arena(np.array(points, np.float32))
        except ValueError as exc:
            raise UserError(f"{exc} Ecken neu setzen.") from exc
        self._drop_tracker()
        self.arena = arena
        self.tracker = Tracker(arena)
        self._register("Roboter in die Arena stellen. Falsch zugeordnet? Auf den Roboter klicken.")

    def do_reset_arena(self) -> None:
        self._drop_tracker()
        self.arena = None
        self.phase = "arena"
        self.message = "Die vier Ecken der Arena anklicken."

    def do_new_battle(self) -> None:
        self._arena_ready()
        self._register("Roboter in die Arena stellen. Falsch zugeordnet? Auf den Roboter klicken.")

    def do_abort(self) -> None:
        self._arena_ready()
        self._register("Kampf abgebrochen.")

    def do_pick(self, x: float, y: float, slot: int) -> None:
        if self.phase != "register":
            raise UserError("Roboter zuordnen geht nur vor dem Start.")
        if slot not in (1, 2):
            raise UserError("Unbekannter Roboter.")
        self.seeds[slot - 1] = (float(x), float(y))

    def do_start(self, names: list[str] | None = None) -> None:
        if self.phase == "ready":
            # Der VS-Bildschirm wartet auf die Moderation, damit die Ansage nicht unter Zeitdruck steht.
            self.phase = "countdown"
            self.phase_until = time.monotonic() + COUNTDOWN_S
            self.message = "Countdown läuft."
            return
        if self.phase in ("intro", "countdown"):
            raise UserError("Das Intro läuft noch, danach mit 'Start' den Countdown auslösen."
                            if self.phase == "intro" else "Der Countdown läuft schon.")
        if self.phase != "register" or self.tracker is None:
            raise UserError("Erst die Arena festlegen und 'Neuer Kampf' drücken.")
        if any(p is None for p in self.proposal):
            raise UserError("Es sind noch nicht beide Roboter erkannt.")
        model = self.segmenter
        if model is not None and not model.ready.is_set() and not model.error:
            # Sonst liefe dieser Kampf ohne EdgeTAM, obwohl es eingeschaltet ist.
            raise UserError("EdgeTAM lädt noch, gleich noch einmal 'Start'.")
        self._set_names(names)
        tracker, battle = self.tracker, self.battle

        def lock_in():
            arbiter = Arbiter(model, self._model_view) if self._model_ready() else None
            try:
                tracker.start(self.names, arbiter, time.monotonic())
            except ValueError as exc:
                tracker.reset()
                raise UserError(f"{exc} Roboter hinstellen und erneut 'Start'.") from exc
            with self._lock:
                # Während EdgeTAM die Roboter lernt, kann neu begonnen worden sein.
                if self.tracker is not tracker or self.battle != battle or self.phase != "register":
                    return
                self.battle += 1
                self.phase_until = time.monotonic() + self.cfg.intro_s
                if self.cfg.intro_s > 0:
                    self.phase = "intro"
                    self.message = "Intro läuft."
                else:
                    # Ohne Intro auch kein VS und kein Countdown: sofort kämpfen, etwa zum Testen.
                    self._begin_fight(time.monotonic())

        self._background("Kampf starten", lock_in)

    def _begin_fight(self, t: float) -> None:
        self.game = Game(self.cfg, [(1, self.names[0]), (2, self.names[1])], t, size=self.arena.size)
        self.fight_start, self.fight_end = t, None
        self.phase = "fight"
        self.message = "Kampf läuft."

    def do_spawn(self, kind: str) -> None:
        if self.phase != "fight" or self.game is None:
            raise UserError("Spawnen geht nur im laufenden Kampf.")
        if kind not in ("obstacle", "powerup"):
            raise UserError("Unbekanntes Objekt.")
        name = "Hindernis" if kind == "obstacle" else "Power-up"
        if not self.game.spawn(kind, time.monotonic(), self._robot_inputs()):
            # Auch im Zustand: Sonst überschreibt das nächste Bild die Meldung, Tastenkürzel sähen sie nie.
            self.message = (f"Kein freier Platz für {name}: Die Arena ist zu klein oder von Robotern und "
                            "Objekten belegt. Warte, bis Objekte verschwinden oder die Roboter Platz machen.")
            raise UserError(self.message)
        self.message = f"{name} gespawnt."

    def do_shrink(self) -> None:
        if self.phase != "fight" or self.game is None:
            raise UserError("Die Arena schrumpft nur im laufenden Kampf.")
        if not self.game.start_shrink(time.monotonic()):
            raise UserError("Die Arena schrumpft bereits.")
        self.message = "Arena schrumpft."

    def do_hud(self, on: bool) -> None:
        self.hud = bool(on)

    def do_profile(self, player: int, name: str = "", **fields: str) -> None:
        if player not in (1, 2):
            raise UserError("Unbekannter Roboter.")
        if set(fields) - set(PROFILE_EMPTY):
            raise UserError("Unbekanntes Feld im Steckbrief.")
        self.profiles[player - 1] = {k: str(fields.get(k) or "").strip() for k in PROFILE_EMPTY}
        # Ab dem Start hängt der Name am laufenden Kampf; davor braucht ihn schon die VS-Vorschau.
        if self.phase not in LIVE_PHASES:
            self.names[player - 1] = str(name).strip() or f"Roboter {player}"

    def do_name(self, player: int, name: str) -> None:
        if player not in (1, 2):
            raise UserError("Unbekannter Roboter.")
        self.player_joined(player, str(name).strip() or f"Roboter {player}")

    def do_kick(self, slot: int) -> None:
        if self.lobby is None or slot not in (1, 2):
            raise UserError("Unbekannter Spielerplatz.")
        name = self.lobby.kick(slot)
        if name is None:
            raise UserError(f"Platz {slot} ist schon frei.")
        self.message = f"{name} von Platz {slot} entfernt."

    def player_joined(self, slot: int, name: str) -> None:
        """Neuer Name für einen Platz; im laufenden Kampf gilt er erst ab dem nächsten."""
        with self._lock:
            if self.phase in LIVE_PHASES:
                self._pending_names[slot] = name
            else:
                self._pending_names.pop(slot, None)
                self.names[slot - 1] = name

    def do_ko(self, player: int) -> None:
        if self.phase != "fight" or self.game is None:
            raise UserError("K.O. geht nur im laufenden Kampf.")
        if player not in (1, 2):
            raise UserError("Unbekannter Roboter.")
        t = time.monotonic()
        self.game.knockout(player, t)
        self._check_finished(t)

    def do_ulti(self, player: int) -> None:
        if self.phase != "fight" or self.game is None:
            raise UserError("Die Ulti geht nur im laufenden Kampf.")
        if player not in (1, 2):
            raise UserError("Unbekannter Roboter.")
        p = self.game.player(player)
        if p.ulti_used:
            raise UserError(f"{p.name} hat die Ulti schon benutzt.")
        if self.game.shot is not None:
            raise UserError("Es zielt gerade schon ein Laser.")
        if not self.game.ulti_ready(p):
            raise UserError(f"Ulti von {p.name} ist noch nicht geladen.")
        if not self.game.fire_ulti(player, time.monotonic()):
            raise UserError("Kein Ziel: beide Roboter müssen schon gesehen worden sein.")

    def do_cue(self, kind: str, media: dict | None = None, id: int | None = None) -> None:  # noqa: A002
        t = time.monotonic()
        if kind == "stop":
            self.memes = []
        elif kind == "ended":
            self.memes = [m for m in self.memes if m["id"] != id]
        elif kind == "media":
            if not (media and media.get("url")):
                raise UserError("Medium fehlt.")
            running = next((m for m in self.memes if m["media"]["url"] == media["url"]), None)
            if running is not None:
                # Zweiter Klick stoppt ganz; der nächste startet wieder von vorn.
                self.memes.remove(running)
            else:
                self._meme_ids += 1
                rng = self._meme_rng
                # Position als Anteil des freien Platzes; jede Bühne rechnet sie mit der echten Größe um.
                self.memes.append({"id": self._meme_ids, "media": media, "since": t,
                                   "x": rng.random(), "y": rng.random(),
                                   "tilt": round(rng.uniform(-4, 4), 1)})
        else:
            raise UserError("Unbekannte Einblendung.")

    def _meme_state(self, t: float) -> list[dict]:
        def limit(m: dict) -> float:
            if m["media"].get("cutout"):
                return CUTOUT_LIMIT_S
            return MEME_LIMIT_S.get(m["media"].get("mime", "").split("/")[0], CUTOUT_LIMIT_S)

        self.memes = [m for m in self.memes if t - m["since"] < limit(m)]
        return [{"id": m["id"], "media": m["media"], "played": round(t - m["since"], 2),
                 "x": m["x"], "y": m["y"], "tilt": m["tilt"]}
                for m in self.memes]

    def do_balancing(self, key: str, value: float) -> None:
        # Spiel und Oberfläche lesen dasselbe cfg-Objekt, daher greift die Änderung sofort, auch im Kampf.
        self._set_balancing(key, value)
        self._save_balancing()

    def do_balancing_reset(self) -> None:
        for key, value in self.balancing_defaults.items():
            setattr(self.cfg, key, value)
        if self.balancing_file is not None:
            self.balancing_file.unlink(missing_ok=True)
        self.message = "Balancing auf Standardwerte zurückgesetzt."

    def _set_balancing(self, key: str, value) -> None:
        if key not in BALANCING:
            raise UserError("Unbekannter Balancing-Wert.")
        try:
            number = float(value)
        except (TypeError, ValueError):
            number = math.nan
        low, high = BALANCING[key]
        if not math.isfinite(number) or number < low or (high is not None and number > high):
            limit = f"von {low:g} bis {high:g}" if high is not None else f"ab {low:g}"
            raise UserError(f"Balancing: bitte eine Zahl {limit} eingeben (rot markiertes Feld).")
        setattr(self.cfg, key, number)

    def _load_balancing(self) -> None:
        path = self.balancing_file
        if path is None or not path.is_file():
            return
        try:
            saved = json.loads(path.read_text("utf-8"))
        except (OSError, ValueError):
            log.warning("%s ist unlesbar, Balancing bleibt bei den Standardwerten.", path)
            return
        for key, value in saved.items():
            try:
                self._set_balancing(key, value)
            except UserError:
                # Von Hand verbogene oder veraltete Einträge sollen den Start nicht verhindern.
                log.warning("Balancing-Wert %s=%r ignoriert.", key, value)

    def _save_balancing(self) -> None:
        path = self.balancing_file
        if path is None:
            return
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps({k: getattr(self.cfg, k) for k in BALANCING}, indent=1), "utf-8")
        tmp.replace(path)

    def _set_names(self, names: list[str] | None) -> None:
        given = list(names or [])[:2] + ["", ""]
        self.names = [str(n).strip() or f"Roboter {i + 1}" for i, n in enumerate(given[:2])]

    def _arena_ready(self) -> None:
        if self.tracker is None:
            raise UserError("Zuerst die vier Ecken der Arena anklicken.")

    def _register(self, message: str) -> None:
        self.tracker.reset()
        # Neue Kampfnummer, damit ein noch laufender Start des alten Kampfs nichts mehr übernimmt.
        self.battle += 1
        self.seeds = {}
        self.proposal = [None, None]
        self.game = None
        self.robots = []
        self.contact = False
        self.fight_start = self.fight_end = None
        self.phase = "register"
        self.message = message
        for slot, name in self._pending_names.items():
            self.names[slot - 1] = name
        self._pending_names.clear()

    def _drop_tracker(self) -> None:
        if self.tracker is not None:
            self.tracker.reset()
        self.tracker = None
        self.game = None
        self.robots = []
        self.proposal = [None, None]
        self.seeds = {}
        self.contact = False
        self.fight_start = self.fight_end = None

    def _model_view(self, view: np.ndarray) -> np.ndarray:
        """Was EdgeTAM sieht; Anlernen und Prüfen müssen gleich aussehen, sonst passt der Anker nie."""
        if self.cfg.white_background:
            return whiten(view, foreground(view))
        return np.ascontiguousarray(view)

    def _model_ready(self) -> bool:
        return self.segmenter is not None and self.segmenter.ready.is_set()

    # ---------- Verarbeitung ----------

    def _robot_inputs(self) -> list[RobotInput]:
        return [RobotInput(o.id, o.present, o.pos, o.vel, o.radius, o.inside, o.outline, o.edge)
                for o in self.robots]

    def _loop(self) -> None:
        last_seq = -1
        while not self._stop.is_set():
            frame = self.camera.latest()
            if frame is None or frame.seq == last_seq:
                time.sleep(0.004)
                continue
            last_seq = frame.seq
            try:
                with self._lock:
                    self._publish(frame.image, frame.seq)
            except Exception:  # noqa: BLE001 – ein kaputter Frame darf die Anzeige nicht beenden.
                log.exception("Anzeige fehlgeschlagen")

    def _track_loop(self) -> None:
        last_seq, last_done = -1, None
        while not self._stop.is_set():
            frame = self.camera.latest()
            if frame is None or frame.seq == last_seq or self.tracker is None:
                if self.tracker is None:
                    self.track_fps, self.latency_ms, last_done = 0.0, 0.0, None
                time.sleep(0.004)
                continue
            # Immer das neueste Bild: lieber Bilder auslassen als dem Geschehen hinterherlaufen.
            last_seq = frame.seq
            try:
                self._process(frame.image, frame.t)
                self.track_error = None
            except Exception as exc:  # noqa: BLE001 – ein kaputter Frame darf das Tracking nicht beenden.
                if self.track_error is None:
                    log.exception("Tracking fehlgeschlagen")
                self.track_error = f"Tracking-Fehler: {exc}"
            done = time.monotonic()
            # Ende zu Ende: Bildrate inklusive Warten auf die Kamera, Verzögerung ab Aufnahme des Bildes.
            # Geglättet, damit die Anzeige bei einzelnen langsamen Bildern nicht springt.
            latency = 1000.0 * (done - frame.t)
            self.latency_ms = latency if self.latency_ms == 0 else 0.8 * self.latency_ms + 0.2 * latency
            if last_done is not None:
                fps = 1.0 / max(1e-3, done - last_done)
                self.track_fps = fps if self.track_fps == 0 else 0.8 * self.track_fps + 0.2 * fps
            last_done = done

    def _process(self, image: np.ndarray, t: float) -> None:
        tracker, phase = self.tracker, self.phase
        if tracker is None:
            return
        if phase == "register":
            masks = tracker.propose(image, dict(self.seeds))
            with self._lock:
                if self.tracker is tracker and self.phase == "register":
                    self.proposal = [tracker.outline(m) for m in masks]
            return
        if phase not in LIVE_PHASES:
            return
        # Auch während des Intros verfolgen, sonst verliert der Tracker die Roboter vor dem ersten Treffer.
        robots, contact = tracker.update(image, t)
        with self._lock:
            # Während des Bildes kann abgebrochen oder neu begonnen worden sein.
            if self.tracker is tracker and self.phase in LIVE_PHASES:
                self._apply(robots, contact, t)

    def _apply(self, robots: list, contact: bool, t: float) -> None:
        self.robots, self.contact = robots, contact
        if self.phase == "intro" and t >= self.phase_until:
            self.phase = "ready"
            self.message = "VS-Bildschirm läuft. Start drückt den Countdown."
        if self.phase == "countdown" and t >= self.phase_until:
            self._begin_fight(t)
        if self.phase == "fight" and self.game is not None:
            self.game.tick(t, self._robot_inputs(), self.contact)
            self._check_finished(t)

    def _check_finished(self, t: float) -> None:
        if self.game.finished:
            self.phase = "finished"
            self.fight_end = t
            winner = self.game.player(self.game.winner).name if self.game.winner else None
            self.message = f"{winner} gewinnt!" if winner else "Unentschieden!"

    # ---------- Ausgabe an die Oberfläche ----------

    @staticmethod
    def _circle(center, radius: float) -> list[list[float]]:
        angles = np.linspace(0, 2 * np.pi, CIRCLE_POINTS, endpoint=False)
        pts = np.stack([center[0] + radius * np.cos(angles), center[1] + radius * np.sin(angles)], axis=1)
        return _points(pts)

    def _model_state(self) -> dict:
        model = self.segmenter
        if model is None:
            return {"enabled": False, "ready": False, "error": None, "device": None, "corrections": 0}
        arbiter = self.tracker.arbiter if self.tracker is not None else None
        return {"enabled": True, "ready": model.ready.is_set(),
                "error": model.error or (arbiter.error if arbiter else None), "device": model.device_label,
                "corrections": self.tracker.corrections if self.tracker is not None else 0}

    def state(self, t: float) -> dict:
        robots = []
        for o in self.robots:
            p = self.game.player(o.id) if self.game else None
            robots.append({
                "id": o.id, "name": p.name if p else self.names[o.id - 1], "present": o.present,
                "hp": round(p.hp, 1) if p else self.cfg.start_hp, "max_hp": self.cfg.start_hp,
                "outside": bool(p and p.outside_since is not None),
                "ulti": {"charge": round(self.game.ulti_charge(p), 2), "ready": self.game.ulti_ready(p),
                         "used": p.ulti_used} if p else {"charge": 0.0, "ready": False, "used": False},
                "center": _points(o.pos), "contour": _points(o.outline),
            })
        items, events = [], []
        if self.game:
            for i in self.game.items:
                items.append({"id": i.id, "kind": i.kind, "center": _points(i.pos),
                              "poly": self._circle(i.pos, i.radius), "armed": i.armed(t),
                              "ttl": round(i.expires - t, 1)})
            events = [{**e, "t": None} for e in self.game.events]
        zone = self.game.zone(t) if self.game else None
        shot = self.game.shot if self.game else None
        if shot is not None:
            shot = {"player": shot["player"], "from": _points(np.array([shot["from"]]))[0],
                    "to": _points(np.array([shot["to"]]))[0], "left": round(max(0.0, shot["fire_at"] - t), 2),
                    "aim": self.cfg.ulti_aim_s}
        if zone is not None:
            x0, y0, x1, y1 = zone
            zone = _points([[x0, y0], [x1, y0], [x1, y1], [x0, y1]])
        arena = self.arena
        elapsed = None
        if self.fight_start is not None:
            elapsed = round(max(0.0, (self.fight_end or t) - self.fight_start), 1)
        vs = self.phase == "ready"
        left = round(max(0.0, self.phase_until - t), 1)
        return {
            "phase": self.phase, "battle": self.battle, "message": self.message, "busy": self.busy,
            "camera": {"source": self.camera.source, "error": self.camera.error},
            "tracking": {"fps": round(self.track_fps, 1), "latency_ms": round(self.latency_ms),
                         "error": self.track_error},
            "model": self._model_state(),
            "arena": None if arena is None else {"corners": arena.corners.tolist(),
                                                 "size": [round(s, 1) for s in arena.size]},
            "proposal": [{"slot": i + 1, "contour": _points(c)} for i, c in enumerate(self.proposal)]
            if self.phase == "register" else [],
            "robots": robots, "contact": self.contact, "items": items, "events": events, "zone": zone,
            "winner": (self.game.player(self.game.winner).name
                       if self.game and self.game.finished and self.game.winner else None),
            "finished": bool(self.game and self.game.finished),
            "intro": left if self.phase == "intro" else None,
            "countdown": left if self.phase == "countdown" else None,
            "memes": self._meme_state(t), "elapsed": elapsed, "hud": self.hud, "vs": vs, "names": self.names,
            "profiles": self.profiles, "shot": shot,
            "balancing": {k: getattr(self.cfg, k) for k in BALANCING},
            "lobby": self.lobby.public() if self.lobby else {"players": [], "online": {}},
            # Zähler statt Liste: das Soundboard lädt /media nur neu, wenn sich der Ordner geändert hat.
            "board": {"rev": self.board_rev, "keying": dict(self.keying)},
        }

    def _publish(self, image: np.ndarray, seq: int) -> None:
        arena = self.arena
        if arena is None:
            # Nur zum Ecken-Setzen gibt es das rohe Kamerabild.
            h, w = image.shape[:2]
            scale = min(1.0, self.cfg.stream_max_width / w)
            out = cv2.resize(image, (int(w * scale), int(h * scale))) if scale < 1 else image
            frame = {"w": w, "h": h, "kind": "camera"}
        else:
            # Nie mehr Auflösung als die Kamera in der Arena tatsächlich hat.
            px = min(self.cfg.stream_max_width, arena.extent) / (UNITS + 2 * VIEW_PAD)
            out = arena.warp(image, px, VIEW_PAD)
            frame = {"w": round(arena.size[0], 1), "h": round(arena.size[1], 1), "kind": "arena",
                     "pad": VIEW_PAD}
        ok, jpeg = cv2.imencode(".jpg", out, [cv2.IMWRITE_JPEG_QUALITY, self.cfg.jpeg_quality])
        if not ok:
            return
        state = self.state(time.monotonic())
        state["frame"] = frame
        header = json.dumps(state, separators=(",", ":")).encode()
        self.packet = (seq, len(header).to_bytes(4, "little") + header + jpeg.tobytes())

    def publish_idle(self) -> None:
        """Ohne Kamerabild trotzdem den Zustand senden, damit Fehlermeldungen ankommen."""
        if self.camera.latest() is not None:
            return
        state = self.state(time.monotonic())
        state["frame"] = None
        header = json.dumps(state, separators=(",", ":")).encode()
        self.packet = (self.packet[0] + 1, len(header).to_bytes(4, "little") + header)
